package com.sky.handler;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.junit.jupiter.MockitoExtension;
import com.sky.result.Result;
import static org.junit.jupiter.api.Assertions.*;

@ExtendWith(MockitoExtension.class)
class GlobalExceptionHandlerTest {

    @InjectMocks
    private GlobalExceptionHandler globalExceptionHandler;

    @Test
    @DisplayName("正向测试：验证修复后的NumberFormatException处理器能返回正确的错误消息")
    void testExceptionHandler_NumberFormatException_ShouldReturnCorrectErrorMessage() {
        // Arrange
        NumberFormatException ex = new NumberFormatException("For input string: \"abc\"");

        // Act
        Result<String> result = globalExceptionHandler.exceptionHandler(ex);

        // Assert
        assertNotNull(result);
        assertEquals("请求参数格式错误，必须是数字", result.getMsg());
        assertNotEquals(1, result.getCode());
    }

    @Test
    @DisplayName("边界测试：验证原始异常（输入字符串'abc'导致的NumberFormatException）现在能被正确处理而不抛出")
    void testExceptionHandler_OriginalExceptionInput_ShouldNotThrow() {
        // Arrange: 模拟原始异常场景
        NumberFormatException ex = new NumberFormatException("For input string: \"abc\"");

        // Act & Assert: 确保方法调用不会抛出异常
        assertDoesNotThrow(() -> {
            Result<String> result = globalExceptionHandler.exceptionHandler(ex);
            assertNotNull(result);
            assertEquals("请求参数格式错误，必须是数字", result.getMsg());
        });
    }

    @Test
    @DisplayName("边界测试：验证各种数字格式异常输入都能被正确处理")
    void testExceptionHandler_VariousNumberFormatInputs_ShouldBeHandled() {
        // Arrange & Act & Assert
        // 测试输入为非数字字符串
        assertDoesNotThrow(() -> {
            Result<String> result1 = globalExceptionHandler.exceptionHandler(
                new NumberFormatException("For input string: \"xyz\""));
            assertNotNull(result1);
            assertEquals("请求参数格式错误，必须是数字", result1.getMsg());
        });

        // 测试输入为空字符串
        assertDoesNotThrow(() -> {
            Result<String> result2 = globalExceptionHandler.exceptionHandler(
                new NumberFormatException("For input string: \"\""));
            assertNotNull(result2);
            assertEquals("请求参数格式错误，必须是数字", result2.getMsg());
        });
    }

    @Test
    @DisplayName("空值/null处理：验证异常消息为null时处理器仍能正常工作")
    void testExceptionHandler_NullMessage_ShouldHandleGracefully() {
        // Arrange: 创建消息为null的NumberFormatException
        NumberFormatException ex = new NumberFormatException(null);

        // Act
        Result<String> result = globalExceptionHandler.exceptionHandler(ex);

        // Assert: 即使异常消息为null，处理器也应该返回固定的错误消息
        assertNotNull(result);
        assertEquals("请求参数格式错误，必须是数字", result.getMsg());
    }
}
